const items = [];
for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  const binaryKeys = Object.keys(item.binary || {});
  if (binaryKeys.length === 0) throw new Error('No se recibió ninguna foto.');
  const key = binaryKeys[0];
  const binary = item.binary[key];
  const buffer = await this.helpers.getBinaryDataBuffer(i, key);
  const base64 = buffer.toString('base64');
  let mediaType = binary.mimeType || 'image/jpeg';
  if (!['image/jpeg','image/png','image/webp','image/gif'].includes(mediaType)) mediaType = 'image/jpeg';
  const sel = (item.json['Qué generar'] || 'Ambos').toLowerCase();
  const mode = sel.includes('stories') ? 'stories' : sel.includes('tiktok') ? 'tiktok' : 'both';
  items.push({ json: { base64, mediaType, mode, filename: binary.fileName || 'foto' } });
}
return items;

const out = [];
for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  const text = item.json.content?.[0]?.text || '';
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}') + 1;
  let plan;
  try { plan = JSON.parse(text.slice(start, end)); }
  catch (e) { plan = { error: 'No se pudo parsear', raw: text }; }
  // Recuperar base64 del nodo Preparar Imagen (2 nodos atrás)
  const prepNode = $('Preparar Imagen').all()[i] || $('Preparar Imagen').first();
  plan._base64 = prepNode?.json?.base64 || '';
  plan._mediaType = prepNode?.json?.mediaType || 'image/jpeg';
  out.push({ json: plan });
}
return out;

const p = $input.first().json;

if (p.error) {
  return [{ json: { html: `<div style="font-family:sans-serif;padding:24px;color:#ff6b6b">❌ Error: ${p.error}</div>` } }];
}

const imgSrc = p._base64 ? `data:${p._mediaType || 'image/jpeg'};base64,${p._base64}` : '';

// Helpers
function esc(t){return (t||'').replace(/</g,'&lt;').replace(/"/g,'&quot;');}
const W=195, H=346;
const photoBg = imgSrc ? `background:url('${imgSrc}') center/cover no-repeat;` : `background:linear-gradient(160deg,#222,#0d0d0d);`;
const logoTag = `<div style="position:absolute;top:11px;right:12px;font-family:Georgia,serif;font-size:14px;color:#fff;letter-spacing:2px;z-index:5;text-shadow:0 1px 4px rgba(0,0,0,.6)">kÖr</div>`;
const handle = `<div style="position:absolute;bottom:9px;left:0;right:0;text-align:center;color:rgba(255,255,255,.6);font-size:8px;letter-spacing:1px;z-index:5">@_korsv</div>`;
const frame = inner => `<div style="position:relative;width:${W}px;height:${H}px;border-radius:16px;overflow:hidden;flex-shrink:0;${photoBg}">${inner}${logoTag}${handle}</div>`;

// Cada template se ve distinto, como las marcas de gym de verdad
function storyPreview(s){
  const t = (s.template||'MOTIVATION').toUpperCase();
  const head = esc(s.headline);
  const txt = esc(s.overlay_text);
  const prod = esc(s.product);
  const price = esc(s.price);
  const cta = esc(s.cta) || 'Ver más';

  if(t==='DROP'){
    return frame(`
    <div style="position:absolute;inset:0;background:linear-gradient(to top,rgba(0,0,0,.8),rgba(0,0,0,.1) 55%)"></div>
    <div style="position:absolute;top:42px;left:0;right:0;text-align:center">
      <div style="display:inline-block;background:#e8175d;color:#fff;font-size:11px;font-weight:800;letter-spacing:3px;padding:5px 14px;transform:rotate(-3deg)">${head||'NUEVO DROP'}</div>
    </div>
    <div style="position:absolute;bottom:46px;left:14px;right:14px">
      <div style="color:#fff;font-size:19px;font-weight:800;line-height:1.1;text-shadow:0 2px 8px #000">${prod||txt}</div>
      ${price?`<div style="color:#e8175d;font-size:22px;font-weight:900;margin-top:4px;text-shadow:0 2px 6px #000">${price}</div>`:''}
    </div>`);
  }
  if(t==='SHOP'){
    return frame(`
    <div style="position:absolute;inset:0;background:linear-gradient(to top,rgba(0,0,0,.85),transparent 60%)"></div>
    <div style="position:absolute;bottom:54px;left:14px;right:14px">
      <div style="color:#fff;font-size:15px;font-weight:700;text-shadow:0 2px 6px #000">${prod||txt}</div>
      ${price?`<div style="color:#fff;font-size:18px;font-weight:900;margin:4px 0">${price}</div>`:''}
      <div style="display:inline-block;background:#fff;color:#0a0a0a;font-size:10px;font-weight:800;letter-spacing:1px;padding:7px 16px;border-radius:20px;margin-top:6px">🛍 ${cta}</div>
    </div>`);
  }
  if(t==='COUNTDOWN'){
    return frame(`
    <div style="position:absolute;inset:0;background:rgba(0,0,0,.55)"></div>
    <div style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:88%;text-align:center">
      <div style="color:rgba(255,255,255,.85);font-size:10px;letter-spacing:3px;margin-bottom:10px">PRÓXIMAMENTE</div>
      <div style="background:rgba(255,255,255,.12);backdrop-filter:blur(6px);border:1px solid rgba(255,255,255,.3);border-radius:14px;padding:14px 10px">
        <div style="color:#fff;font-size:15px;font-weight:800;line-height:1.2">${txt||head}</div>
        <div style="color:#e8175d;font-size:9px;font-weight:700;letter-spacing:2px;margin-top:6px">⏳ ACTIVA EL RECORDATORIO</div>
      </div>
    </div>`);
  }
  if(t==='RESTOCK'){
    return frame(`
    <div style="position:absolute;inset:0;background:linear-gradient(135deg,rgba(0,0,0,.4),rgba(0,0,0,.7))"></div>
    <div style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%) rotate(-8deg);width:90%;text-align:center">
      <div style="border:3px solid #fff;border-radius:8px;padding:10px 8px;background:rgba(232,23,93,.25)">
        <div style="color:#fff;font-size:20px;font-weight:900;letter-spacing:1px;line-height:1">DE VUELTA<br>EN STOCK</div>
      </div>
      <div style="color:#fff;font-size:11px;font-weight:600;margin-top:10px;text-shadow:0 1px 4px #000">${prod||txt}</div>
    </div>`);
  }
  if(t==='UGC'){
    const user = esc(s.username)||'@cliente';
    return frame(`
    <div style="position:absolute;inset:0;background:rgba(0,0,0,.35)"></div>
    <div style="position:absolute;top:38px;left:12px;display:flex;align-items:center;gap:6px;background:rgba(0,0,0,.4);padding:4px 10px 4px 4px;border-radius:20px">
      <div style="width:22px;height:22px;border-radius:50%;background:linear-gradient(45deg,#e8175d,#8b1fd4)"></div>
      <div style="color:#fff;font-size:10px;font-weight:600">${user}</div>
    </div>
    <div style="position:absolute;bottom:50px;left:12px;background:rgba(0,0,0,.45);backdrop-filter:blur(4px);border-radius:12px;padding:8px 12px">
      <div style="color:#fff;font-size:12px;font-weight:600">${txt||'Repost de la comunidad 🖤'}</div>
      <div style="color:rgba(255,255,255,.7);font-size:9px;margin-top:2px">Etiquétanos con tu fit kÖr</div>
    </div>`);
  }
  if(t==='POLL'){
    const a = esc(s.poll_a)||'Sí 🔥', b = esc(s.poll_b)||'Obvio 💪';
    return frame(`
    <div style="position:absolute;inset:0;background:rgba(0,0,0,.4)"></div>
    <div style="position:absolute;top:46%;left:50%;transform:translate(-50%,-50%);width:86%;text-align:center">
      <div style="color:#fff;font-size:14px;font-weight:700;text-shadow:0 2px 6px #000;margin-bottom:12px">${txt||head}</div>
      <div style="display:flex;border-radius:24px;overflow:hidden;box-shadow:0 4px 14px rgba(0,0,0,.4)">
        <div style="flex:1;background:rgba(255,255,255,.92);color:#0a0a0a;font-size:11px;font-weight:700;padding:9px 4px">${a}</div>
        <div style="flex:1;background:#e8175d;color:#fff;font-size:11px;font-weight:700;padding:9px 4px">${b}</div>
      </div>
    </div>`);
  }
  // MOTIVATION (default)
  return frame(`
  <div style="position:absolute;inset:0;background:linear-gradient(to top,rgba(0,0,0,.6),rgba(0,0,0,.3))"></div>
  <div style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:84%;text-align:center">
    <div style="color:#fff;font-size:21px;font-weight:800;line-height:1.15;text-shadow:0 2px 10px #000;letter-spacing:.3px">${txt||head}</div>
  </div>`);
}

let html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
*{box-sizing:border-box;margin:0;padding:0}
body{background:#0a0a0a;color:#fff;font-family:'Helvetica Neue',Arial,sans-serif;padding:20px 16px}
.logo{font-family:Georgia,serif;font-size:24px;letter-spacing:3px;margin-bottom:24px}
.sec{margin-bottom:32px}
.sec-title{font-size:10px;letter-spacing:2px;text-transform:uppercase;color:#666;margin-bottom:14px;border-left:3px solid #e8175d;padding-left:8px}
.analysis{font-size:13px;color:#999;line-height:1.6;background:#141414;padding:14px;border-radius:10px}
.stories-scroll{display:flex;gap:14px;overflow-x:auto;padding-bottom:8px}
.stories-scroll::-webkit-scrollbar{height:4px}.stories-scroll::-webkit-scrollbar-thumb{background:#333;border-radius:2px}
.story-detail{background:#141414;border-radius:10px;padding:12px;margin-top:10px;font-size:12px;color:#888;line-height:1.5}
.script-row{display:flex;gap:10px;padding:7px 0;border-bottom:1px solid #1a1a1a;font-size:12px}
.ts{color:#e8175d;font-weight:700;font-size:10px;min-width:85px;padding-top:1px}
.caption-box{background:#141414;border-radius:10px;padding:14px;font-size:13px;line-height:1.7;white-space:pre-wrap;color:#ddd}
.tags{display:flex;flex-wrap:wrap;gap:5px;margin-top:8px}
.tag{background:rgba(232,23,93,.12);border:1px solid rgba(232,23,93,.25);color:#e8175d;padding:3px 9px;border-radius:20px;font-size:11px}
.btn{display:block;width:100%;margin-top:10px;background:#e8175d;color:#fff;border:none;border-radius:8px;padding:11px;font-size:12px;font-weight:700;cursor:pointer;letter-spacing:1px;text-transform:uppercase}
.btn:active{opacity:.75}
.prompts{background:#141414;border-radius:10px;padding:14px;font-size:11px;color:#777;line-height:1.6}
</style></head><body>
<div class="logo">kÖr</div>`;

// Análisis
if (p.analysis) html += `<div class="sec"><div class="sec-title">Análisis</div><div class="analysis">${p.analysis}</div></div>`;

// Historias — previews visuales
if (p.stories && p.stories.length) {
  html += `<div class="sec"><div class="sec-title">📱 Historias — preview</div>`;
  html += `<div class="stories-scroll">${p.stories.map(s => storyPreview(s)).join('')}</div>`;
  // Detalle de cada historia
  p.stories.forEach(s => {
    const capEsc = (s.caption||'').replace(/`/g,'\\`');
    html += `<div class="story-detail">
      <strong style="color:#e8175d">${(s.template||'').toUpperCase()}</strong> · ${(s.overlay_text||'')}<br><span style="color:#aaa">${s.caption||''}</span>
      <button class="btn" style="margin-top:8px" onclick="navigator.clipboard.writeText(\`${capEsc}\`).then(()=>{this.textContent='✓ Copiado';setTimeout(()=>this.textContent='Copiar caption historia',1500)})">Copiar caption historia</button>
    </div>`;
  });
  html += `</div>`;
}

// TikTok
if (p.tiktok && p.tiktok.format) {
  const tt = p.tiktok;
  html += `<div class="sec"><div class="sec-title">🎬 TikTok [${tt.format}] — ${tt.duration||''}</div>`;
  (tt.script||[]).forEach(s => {
    html += `<div class="script-row"><span class="ts">${s.time||''}</span><span style="color:#ccc">${s.action||''}</span></div>`;
  });
  if (tt.audio) html += `<div style="margin-top:10px;font-size:12px;color:#888">🎵 ${tt.audio}</div>`;
  if (tt.on_screen_text) html += `<div style="font-size:12px;color:#888;margin-top:4px">📝 ${tt.on_screen_text}</div>`;
  html += `</div>`;
}

// Caption
if (p.instagram_caption) {
  const capEsc = p.instagram_caption.replace(/`/g,'\\`');
  html += `<div class="sec"><div class="sec-title">✍️ Caption Instagram</div>
    <div class="caption-box" id="cap">${p.instagram_caption.replace(/</g,'&lt;')}</div>
    <button class="btn" onclick="navigator.clipboard.writeText(\`${capEsc}\`).then(()=>{this.textContent='✓ Copiado';setTimeout(()=>this.textContent='Copiar Caption',1500)})">Copiar Caption</button>
  </div>`;
}

// Hashtags
if (p.hashtags && p.hashtags.length) {
  const tagStr = p.hashtags.map(t=>t.startsWith('#')?t:'#'+t).join(' ');
  const tagEsc = tagStr.replace(/`/g,'\\`');
  html += `<div class="sec"><div class="sec-title">#️⃣ Hashtags</div>
    <div class="tags">${p.hashtags.map(t=>`<span class="tag">${t.startsWith('#')?t:'#'+t}</span>`).join('')}</div>
    <button class="btn" onclick="navigator.clipboard.writeText(\`${tagEsc}\`).then(()=>{this.textContent='✓ Copiado';setTimeout(()=>this.textContent='Copiar Hashtags',1500)})">Copiar Hashtags</button>
  </div>`;
}

// Prompts Higgsfield
if (p.higgsfield_prompts && p.higgsfield_prompts.length) {
  html += `<div class="sec"><div class="sec-title">🎨 Prompts Higgsfield</div><div class="prompts">${p.higgsfield_prompts.map(pr=>pr.replace(/</g,'&lt;')).join('<br><br>')}</div></div>`;
}

html += `</body></html>`;
return [{ json: { html } }];
